import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static int n;
    static int totalStates = 0;
    static int[] bitsCount = new int[250];
    static int[] positionMap = new int[250];
    static int[][] f = new int[10][250];
    static List<List<Integer>> layerSets = new ArrayList<>();
    static Map<Pair, Integer> cacheMap = new HashMap<>();

    static class Pair {
        int layer;
        long mask;

        Pair(int layer, long mask) {
            this.layer = layer;
            this.mask = mask;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return layer == pair.layer && mask == pair.mask;
        }

        @Override
        public int hashCode() {
            return Objects.hash(layer, mask);
        }
    }

    static int fastPow(int base, int power) {
        long result = 1;
        long b = base;
        while (power > 0) {
            if ((power & 1) == 1) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            power >>= 1;
        }
        return (int) result;
    }

    static int recurseDP(int layer, long mask) {
        if (mask == 0) return 0;
        if (layer == n) return 1;
        Pair key = new Pair(layer, mask);
        if (cacheMap.containsKey(key)) return cacheMap.get(key);

        totalStates++;
        int total = 0;
        int maxSubsetMask = (1 << n) - 1;
        for (int subsetMask = 1; subsetMask <= maxSubsetMask; subsetMask++) {
            long next_mask = 0;
            for (int k = 0; k < layerSets.get(layer).size(); k++) {
                if ((mask & (1L << k)) == 0) continue;
                int prevVal = layerSets.get(layer).get(k);
                for (int l = 0; l < n; l++) {
                    if ((subsetMask & (1 << l)) != 0 && (prevVal & (1 << l)) == 0) {
                        next_mask |= 1L << positionMap[prevVal | (1 << l)];
                    }
                }
            }
            long temp = (long) f[layer][subsetMask] * recurseDP(layer + 1, next_mask);
            total = (int) ((total + temp) % MOD);
        }
        cacheMap.put(key, total);
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        int inv100 = fastPow(100, MOD - 2);
        for (int i = 0; i < n; i++) {
            Arrays.fill(f[i], 1);
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int P = Integer.parseInt(st.nextToken());
                int p1 = (int) ((long) P * inv100 % MOD);
                int p0 = (MOD + 1 - p1) % MOD;
                for (int k = (1 << j) - 1; k >= 0; k--) {
                    f[i][k | (1 << j)] = (int) ((long) f[i][k] * p1 % MOD);
                    f[i][k] = (int) ((long) f[i][k] * p0 % MOD);
                }
            }
        }
        int size = 1 << n;
        for (int i = 0; i < size; i++) {
            bitsCount[i] = Integer.bitCount(i);
        }
        for (int i = 0; i < size; i++) {
            while (layerSets.size() <= bitsCount[i]) {
                layerSets.add(new ArrayList<>());
            }
            layerSets.get(bitsCount[i]).add(i);
        }
        for (int i = 0; i < size; i++) {
            int count = bitsCount[i];
            positionMap[i] = layerSets.get(count).size() - 1;
        }
        System.out.println(recurseDP(0, 1L));
    }
}
